// R1-T3 skyline silhouettes (D-057): distant landmarks for the side-edge parallax layer, as SVG.
// Writes art/arenas/sky/<kind>.svg (review copies) and js/view/arena-sky-data.js (what the game loads; SVG as strings, so it works from
// file://) with the per-hood list. Sources: tools/arena-sky/{shapes,hoods}.js. Usage: node prototype/tools/gen-arena-sky.js
'use strict';
const fs = require('fs'), path = require('path');
const ROOT = path.join(__dirname, '..', '..');
const { SHAPES } = require('./arena-sky/shapes.js'), hoods = require('./arena-sky/hoods.js');
const dir = path.join(ROOT, 'art', 'arenas', 'sky'); fs.mkdirSync(dir, { recursive: true });
fs.readdirSync(dir).filter(n => n.endsWith('.svg')).forEach(n => fs.unlinkSync(path.join(dir, n)));
const shapes = {};
Object.keys(SHAPES).forEach(k => { const s = SHAPES[k](); fs.writeFileSync(path.join(dir, k + '.svg'), s.svg); shapes[k] = s; });
Object.keys(hoods).forEach(id => hoods[id].forEach(k => { if (!shapes[k]) throw new Error(id + ' names an unknown skyline shape: ' + k); }));
const out = '// GENERATED by tools/gen-arena-sky.js (R1-T3, D-057). Do not edit by hand. Source: art/arenas/sky/*.svg.\n' +
  'P.ArenaSkyData = ' + JSON.stringify({ shapes, hoods }) + ';\n';
fs.writeFileSync(path.join(ROOT, 'prototype', 'js', 'view', 'arena-sky-data.js'), out);
console.log('arena sky: ' + Object.keys(shapes).length + ' shapes, ' + Object.keys(hoods).length + ' hoods, ' + (out.length / 1024).toFixed(0) + ' KB');
